// ── Valida assinatura Stripe (timing-safe) ────────────────────────────────
const crypto = require('crypto');

const rawBody = $input.first().json.rawBody ?? $input.first().json.body ?? '';
if (!rawBody) throw new Error('MISSING_RAW_BODY');

const sigHeader = $input.first().json.headers?.['stripe-signature'] ?? '';
if (!sigHeader) throw new Error('MISSING_STRIPE_SIGNATURE');

const secret = $env.STRIPE_WEBHOOK_SECRET;
if (!secret) throw new Error('MISSING_WEBHOOK_SECRET');

// Stripe-Signature: t=timestamp,v1=sig1,...
const parts = {};
sigHeader.split(',').forEach(part => {
  const idx = part.indexOf('=');
  if (idx > 0) parts[part.slice(0, idx)] = part.slice(idx + 1);
});

const timestamp = parts['t'];
const v1 = parts['v1'];

if (!timestamp || !v1) throw new Error('INVALID_SIGNATURE_FORMAT');

// Tolerância de 5 minutos
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - parseInt(timestamp, 10)) > 300) {
  throw new Error('SIGNATURE_TIMESTAMP_TOO_OLD');
}

const signedPayload = `${timestamp}.${rawBody}`;
const expectedSig = crypto
  .createHmac('sha256', secret)
  .update(signedPayload, 'utf8')
  .digest('hex');

// Timing-safe comparison
let diff = 0;
if (expectedSig.length !== v1.length) throw new Error('STRIPE_SIGNATURE_MISMATCH');
for (let i = 0; i < expectedSig.length; i++) {
  diff |= expectedSig.charCodeAt(i) ^ v1.charCodeAt(i);
}
if (diff !== 0) throw new Error('STRIPE_SIGNATURE_MISMATCH');

// Parse do evento validado
let event;
try {
  event = JSON.parse(rawBody);
} catch {
  throw new Error('INVALID_JSON_BODY');
}

console.log('[WF-STRIPE] signature_valid', {
  event_id: event.id,
  event_type: event.type,
  timestamp,
});

return [{ json: { event, signature_valid: true } }];

// ── Normaliza evento para billing RPC ────────────────────────────────────
const event = $input.first().json.event;
const type = event.type;
const obj = event.data?.object ?? {};

const SUPPORTED = [
  'checkout.session.completed',
  'invoice.paid',
  'invoice.payment_failed',
  'customer.subscription.deleted',
];

if (!SUPPORTED.includes(type)) {
  console.log('[WF-STRIPE] event_skipped', { event_id: event.id, type });
  return [{ json: { skip: true, reason: `unsupported_event_type:${type}`, event_id: event.id } }];
}

// Extrai metadata — pode estar na session, na invoice ou na subscription
let metadata = obj.metadata ?? {};
if (!metadata.recruta_id) {
  // invoice.paid: metadata fica na subscription
  const subMeta = obj.subscription?.metadata ?? {};
  if (subMeta.recruta_id) metadata = subMeta;
}

const STATUS_MAP = {
  'checkout.session.completed': 'paid',
  'invoice.paid': 'paid',
  'invoice.payment_failed': 'failed',
  'customer.subscription.deleted': 'cancelled',
};

console.log('[WF-STRIPE] event_normalized', {
  event_id: event.id,
  type,
  recruta_id: metadata.recruta_id ?? null,
  correlation_id: metadata.correlation_id ?? null,
});

return [{
  json: {
    skip: false,
    gateway_nome: 'stripe',
    gateway_event_id: event.id,
    status_pagamento: STATUS_MAP[type],
    event_type: type,
    recruta_id: metadata.recruta_id ?? null,
    auth_id: metadata.auth_id ?? null,
    plan_slug: metadata.plan_slug ?? null,
    correlation_id: metadata.correlation_id ?? null,
    amount: obj.amount_total ?? obj.amount_paid ?? null,
    currency: obj.currency ?? null,
    customer_id: obj.customer ?? null,
    subscription_id: obj.subscription ?? obj.id ?? null,
  }
}];
